from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
cases=[c for c in json.loads((o/'trialpage-cases.json').read_text()) if c['id'].endswith('-both')]
(o/'trialpage-baseline-cases.json').write_text(json.dumps(cases,indent=2)+'\n')
inner=(o/'trialpage-inner.html').read_text()+'''<style>.trial-baseline{display:inline-block;width:0;height:0;padding:0;margin:0;vertical-align:baseline}</style><script>for(const e of document.querySelectorAll('.notice strong'))e.insertAdjacentHTML('afterend','<span class="trial-baseline"></span>');function baselineRead(){const p=document.querySelector('.page').getBoundingClientRect();return{id:`${lang}-${viewport}-${mode}`,notices:[...document.querySelectorAll('.notice')].map(e=>{const t=e.querySelector('strong'),b=e.querySelector('.trial-baseline').getBoundingClientRect();return{title:t.textContent,baseline:b.y-p.y,titleWidths:[...t.getClientRects()].map(r=>r.width)}})}};</script>'''
(o/'trialpage-baseline-inner.html').write_text(inner)
frames=''.join(f'<iframe width="{c["viewportWidth"]}" height="1800" src="trialpage-baseline-inner.html?language={"en" if c["english"] else "ko"}&viewport={c["viewportWidth"]}&state=both" style="border:0;display:none"></iframe>' for c in cases)
(o/'trialpage-baseline.html').write_text('''<!doctype html><meta charset="utf-8"><title>TrialPage inline baseline · original</title><p id="state">Measuring inline baselines16</p>'''+frames+'''<script>window.onload=async()=>{const rows=[];for(const f of document.querySelectorAll('iframe')){f.style.display='block';await f.contentDocument.fonts.ready;await Promise.all(f.contentDocument.getAnimations().filter(a=>Number.isFinite(a.effect.getComputedTiming().endTime)).map(a=>a.finished));rows.push(f.contentWindow.baselineRead());f.style.display='none'}const response=await fetch('/evidence/home-trialpage-'+(/Windows/.test(navigator.userAgent)?'windows':'mac')+'-control-ready.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows})});if(!response.ok)throw Error('Record failed');document.getElementById('state').textContent='TrialPage baselines16 recorded'};</script>''')
print('Inline baseline source16 prepared; geometry80 unchanged')
